const fs = require('fs');
var Web3 = require('web3');

const data = fs.readFileSync('./data.csv');
const lines = data.toString().split('\r\n');
const parsedLines = lines.map(l => l.split(','));

const finalData = parsedLines.map(l => ({
    hash: l[0],
    blockNumber: l[1],
    ts: l[2],
    from: l[4],
    to: l[4],
    fn: l[15]
}));


var web3 = new Web3(new Web3.providers.HttpProvider('https://polygon-mainnet.infura.io/v3/3f9967d704884ac0b0136b98e5534f55')); // your web3 provider
const wait = (ms) => new Promise(resolve => setTimeout(resolve, ms));

const parse = async (lines) => {
    for (let index = 0; index < lines.length; index++) {
        const line = lines[index];
        const tx = await web3.eth.getTransaction(line.hash);
        console.log('fuck', tx, line.hash);

        await wait(1000);

        let tx_data = tx.input;
        let input_data = '0x' + tx_data.slice(10);  // get only data without function selector

        if (line.fn === 'Create_lock') {
            let params = web3.eth.abi.decodeParameters(['uint256', 'uint256'], input_data);
            line.data = {
                amount: params[0],
                lock_time: params[1]
            };
        }

        if (line.fn === 'Increase_unlock_time') {
            let params = web3.eth.abi.decodeParameters(['uint256'], input_data);
            line.data = {
                lock_time: params[0]
            };
        }

        if (line.fn === 'Increase_amount') {
            let params = web3.eth.abi.decodeParameters(['uint256'], input_data);
            line.data = {
                amount: params[0]
            };
        }

        fs.writeFileSync("out.json", JSON.stringify(lines, null, 2));
    }


};

parse(finalData);

const BigNumber = require('bignumber.js');
const _data = require('./out.json');

const data = _data.sort((a, b) => a.ts - b.ts);

accounts = {};

const area = (x1, y1, x2, y2) => {
    const area1 = 0.5 * x1 * y1;
    const area2 = 0.5 * x2 * y2;

    // console.log('area', x1, y1, x2, y2, area2 - area1);
    return area2 - area1;
};

const year_4 = 365 * 86400 * 4;
const mahax = (amount, start, end) => {
    if (amount ==0 ) return 0;
    return amount * ((end - start) / year_4);
};

data.forEach(d => {
    const acct = accounts[d.from] || {};

    if (!acct.lastAmount) acct.lastAmount = 0;
    if (!acct.area) acct.area = 0;
    if (!acct.mahax) acct.mahax = 0;

    if (acct.lastTimestamp) {
        acct.area += (
            area(
                acct.lastTimestamp, acct.mahax,
                d.ts, acct.mahax,
            )
        );
    }

    if (d.fn === 'Create_lock') {
        acct.startPoint = d.ts;

        acct.lastLockPeriod = Number(d.data.lock_time);
        acct.lastAmount = Number(d.data.amount) / 1e18;

        acct.lastLockDurationDays = (acct.lastLockPeriod - acct.startPoint) / 86400;
        acct.mahax = mahax(acct.lastAmount, acct.startPoint, acct.lastLockPeriod);
    }

    if (d.fn === 'Increase_unlock_time') {
        acct.lastLockPeriod = Number(d.data.lock_time);

        acct.lastLockDurationDays = (acct.lastLockPeriod - acct.startPoint) / 86400;
        acct.mahax = mahax(acct.lastAmount, acct.startPoint, acct.lastLockPeriod);
    }

    if (d.fn === 'Increase_amount') {
        acct.lastAmount += Number(d.data.amount) / 1e18;

        acct.lastLockDurationDays = (acct.lastLockPeriod - acct.startPoint) / 86400;
        acct.mahax = mahax(acct.lastAmount, acct.startPoint, acct.lastLockPeriod);
    }

    if (d.fn === 'Withdraw') {
        acct.startPoint = 0;
        acct.lastLockPeriod = 0;
        acct.lastAmount = 0;
        acct.lastLockDurationDays = 0;
        acct.mahax = 0;
    }

    acct.lastTimestamp = d.ts;
    accounts[d.from] = acct;
    // console.log(acct, d.fn);
});

const keys = Object.keys(accounts);
keys.forEach(key => {
    const acct = accounts[key] || {};
    acct.area += (
        area(
            acct.lastTimestamp, acct.mahax,
            1640542375, acct.mahax,
        )
    );

    console.log(`${key}, ${acct.mahax}, ${acct.area}`);
});
